BEGIN;
CREATE TABLE IF NOT EXISTS records.facility_sources (
        jail_id text PRIMARY KEY REFERENCES public."Jail"(id), source_id text NOT NULL,
        source_url text NOT NULL, source_vintage text NOT NULL, imported_at timestamptz NOT NULL DEFAULT now(),
        verification_note text NOT NULL);
      CREATE TABLE IF NOT EXISTS records.facility_ingestion_queue (
        jail_id text PRIMARY KEY REFERENCES public."Jail"(id),status text NOT NULL DEFAULT 'source_discovery',
        source_url text,adapter text,notes text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now());
      GRANT SELECT,INSERT,UPDATE,DELETE ON records.facility_sources,records.facility_ingestion_queue TO jailmap_app;
INSERT INTO public."Jail"(id,name,latitude,longitude,"countyId","stateId",website,"isActive","updatedAt")
          SELECT 'census-landmark-1104260206107','Franklin County Jail',44.6972747,-70.1578051,c.id,c."stateId",'https://tigerweb.geo.census.gov/arcgis/rest/services/TIGERweb/Labels/MapServer/12/query?where=OID%3D%271104260206107%27&outFields=NAME%2CMTFCC&f=pjson',false,now()
          FROM public."County" c WHERE c."fipsCode"='23007'
          ON CONFLICT(id) DO UPDATE SET latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,"updatedAt"=now();
